function total(values) {
  if (values.length === 0) return 0;
  for (const val of values) {
    if (!Number.isFinite(val)) {
      throw new Error('Non-numeric or non-finite entry');
    }
  }
  return values.reduce((sum, val) => sum + val, 0);
}

